std::vector<double> k3 = f(x + 0.5 * h * k2, t + 0.5 * h);
std::vector<double> k4 = f(x + h * k3, t + h);

std::vector<double> x_next(x.size());
for (size_t i = 0; i < x.size(); ++i) {
    x_next[i] = x[i] + (h / 6.0) * (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]);
}
